import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.DhJmN6iX.js";const u=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1785336345000}'),n={name:"changelog.md"};function r(d,e,s,l,c,g){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="v0-12-21-2026-07-27" tabindex="-1">v0.12.21 (2026-07-27) <a class="header-anchor" href="#v0-12-21-2026-07-27" aria-label="Permalink to &quot;v0.12.21 (2026-07-27)&quot;">​</a></h2><ul><li><strong>Collapsible Sidebar &amp; Icon Rail</strong>: Interactive minimization toggle for the admin sidebar with smooth transitions to a compact 76px icon rail mode.</li><li><strong>Hover Context Tooltips</strong>: Instant floating context tooltips on hover for minimized navigation items.</li><li><strong>React Portal Dropdowns</strong>: Upgraded <code>Dropdown.tsx</code> to mount menus via <code>createPortal</code>, floating user account menus cleanly to the right of the minimized rail without clipping.</li><li><strong>Role-Based Navigation &amp; Explorer Pruning</strong>: Automatic filtering of sidebar links and dashboard quick-actions based on active user role permissions (<code>super_admin</code>, <code>admin</code>, <code>editor</code>, <code>author</code>, <code>customer</code>).</li><li><strong>React Hydration &amp; Vite Optimization</strong>: Resolved React hydration mismatch errors in <code>UserDetail.tsx</code> and optimized client directives (<code>client:only=&quot;react&quot;</code>) for dynamic dashboard metric cards and charts.</li></ul><h2 id="v0-12-20-2026-07-27" tabindex="-1">v0.12.20 (2026-07-27) <a class="header-anchor" href="#v0-12-20-2026-07-27" aria-label="Permalink to &quot;v0.12.20 (2026-07-27)&quot;">​</a></h2><ul><li><strong>Registration Controls</strong>: Added <code>Enable User Registration</code> toggle in System Settings global (<code>/admin/settings/system</code>) to enable/disable public sign-ups on <code>/admin/register</code> and <code>POST /api/auth/register</code>.</li><li><strong>Configurable Default Registration Role</strong>: Added <code>Default Registration Role</code> setting allowing administrators to set the automatic role (<code>customer</code>, <code>author</code>, <code>editor</code>, <code>admin</code>) for newly registered users.</li><li><strong>RBAC &amp; Role Assignment Protection</strong>: Restricted user role modifications exclusively to <code>super_admin</code> users across REST API endpoints (<code>POST /api/users</code>, <code>PATCH /api/users/:id</code>) and Admin UI components (<code>UserDetail</code>, <code>UserManagement</code>).</li><li><strong>Users REST API Fix</strong>: Fixed <code>GET /api/users</code> endpoint to query <code>sessionAuthAdapter.findUsers()</code> directly from auth storage.</li></ul><h2 id="v0-12-18-2026-07-25" tabindex="-1">v0.12.18 (2026-07-25) <a class="header-anchor" href="#v0-12-18-2026-07-25" aria-label="Permalink to &quot;v0.12.18 (2026-07-25)&quot;">​</a></h2><ul><li><strong>Collection Overrides &amp; Dynamic Content</strong>: Full support for overriding dynamic content &amp; block fields (e.g. <code>&quot;content.recentFeed.selectedItems&quot;</code>).</li><li><strong>Admin UI &amp; Layout Fixes</strong>: Fixed <code>TabsLayout</code> key preservation during hot reload, excluded discriminator field names from tab item headers, and improved dynamic relationship target title resolution.</li><li><strong>Astro Integration</strong>: Added React deduplication in Astro Vite configuration and fixed SEO tab selector for collection fields.</li><li><strong>Templates</strong>: Updated <code>menuCollection</code> template to include an optional label field for external links.</li></ul><h2 id="v0-12-17-2026-07-24" tabindex="-1">v0.12.17 (2026-07-24) <a class="header-anchor" href="#v0-12-17-2026-07-24" aria-label="Permalink to &quot;v0.12.17 (2026-07-24)&quot;">​</a></h2><ul><li><strong>Collection Overrides</strong>: Added support for overriding dynamic content &amp; block fields (e.g. <code>&quot;content.recentFeed.selectedItems&quot;</code>).</li><li><strong>Admin UI Enhancements</strong>: Improved array item header resolution (dynamic relationship target title fetching, discriminator name filtering).</li><li><strong>SEO Tabs Integration</strong>: Automatic injection of SEO Settings tab for collections with <code>seo: true</code>.</li><li><strong>Database Migrations</strong>: Added database-agnostic legacy tabs flattening utility (<code>scripts/flatten-tabs.mjs</code>).</li></ul><h2 id="v0-12-16-2026-07-21" tabindex="-1">v0.12.16 (2026-07-21) <a class="header-anchor" href="#v0-12-16-2026-07-21" aria-label="Permalink to &quot;v0.12.16 (2026-07-21)&quot;">​</a></h2><ul><li>Rebuild and release of Kyro CMS v0.12.16.</li></ul>',11)])])}const h=o(n,[["render",r]]);export{u as __pageData,h as default};
